import{_ as e,o as a,c as i,ao as t}from"./chunks/framework.BFkeCY5U.js";const k=JSON.parse('{"title":"Sharding","description":"","frontmatter":{},"headers":[],"relativePath":"guide/sharding.md","filePath":"guide/sharding.md","lastUpdated":null}'),n={name:"guide/sharding.md"};function d(h,s,r,l,o,p){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="Sharding" tabindex="-1">Sharding <a class="header-anchor" href="#Sharding" aria-label="Permalink to &quot;Sharding {#Sharding}&quot;">​</a></h1><p>Above ~1000 guilds (2500 at the hard limit) Discord requires splitting the gateway connection into shards. Nobelium handles the whole dance:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Client</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(token)             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># shards=:auto is the default</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">start!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(client)</span></span></code></pre></div><p>With <code>:auto</code>, the client asks <code>GET /gateway/bot</code> for the recommended shard count and Discord&#39;s <code>max_concurrency</code>, then brings shards up in the mandated identify buckets (one identify per bucket per five seconds).</p><p>Force a count if you know better:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Client</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(token; shards</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Every shard feeds the same handler registry and cache, so your code doesn&#39;t change at all. A guild&#39;s events always arrive on the shard <code>(guild_id &gt;&gt; 22) % shard_count</code> — the client uses that internally to route <code>request_guild_members!</code> and voice-state updates to the right connection.</p><p>For very large bots that spread shards across processes, run one <code>Client</code> per process with an explicit shard count and split the shard IDs yourself — the building blocks (<code>Nobelium.Shard</code>) are public enough to compose.</p>`,8)])])}const g=e(n,[["render",d]]);export{k as __pageData,g as default};
